() => {
  // Extract search result items
  const items = [];
  // Get all product result divs (exclude sponsored)
  const resultDivs = document.querySelectorAll('div.s-result-item[data-component-type="s-search-result"]');
  let count = 0;
  for (const div of resultDivs) {
    if (count >= 6) break;
    const titleEl = div.querySelector('h2 a span, h2 span');
    const priceEl = div.querySelector('.a-price .a-offscreen');
    const sponsoredEl = div.querySelector('[data-component-type="sp-sponsored-result"]');
    const ratingEl = div.querySelector('[aria-label*="Rated"]');
    if (titleEl) {
      items.push({
        title: titleEl.textContent.trim().substring(0, 150),
        price: priceEl ? priceEl.textContent.trim() : 'N/A',
        rating: ratingEl ? ratingEl.getAttribute('aria-label') : 'N/A',
        sponsored: !!sponsoredEl
      });
      count++;
    }
  }
  return items;
}

